/**
 * haptic.js — VelaGuard 触觉反馈工具模块
 *
 * 智能手表的核心交互优势：手腕是触觉敏感区域。
 * 每次重要操作都应配对一个独特的震动模式，让用户通过触觉确认操作状态。
 */

import vibrator from "@system.vibrator"

/**
 * 短震：按钮点击、页面切换、轻交互
 */
export function tap() {
  try {
    vibrator.vibrate({ mode: 'short', duration: 15 })
  } catch (e) { /* 降级：无震动 */ }
}

/**
 * 中震：重要选择、状态确认
 */
export function confirm() {
  try {
    vibrator.vibrate({ mode: 'short', duration: 30 })
  } catch (e) { /* 降级 */ }
}

/**
 * 长震：SOS触发、紧急确认、重大事件
 */
export function urgent() {
  try {
    vibrator.vibrate({ mode: 'long', duration: 500 })
  } catch (e) { /* 降级 */ }
}

/**
 * 双震：错误、警告、取消操作
 */
export function error() {
  try {
    vibrator.vibrate({ mode: 'double', duration: 20 })
  } catch (e) { /* 降级 */ }
}

/**
 * 渐进式短震：SOS长按过程中使用
 * 每 500ms 触发一次短震，让用户通过触觉感知进度
 * @returns {Function} cancel - 调用以停止渐进震动
 */
export function progressiveTap(intervalMs) {
  var ms = intervalMs || 500
  var timer = null

  // 立即触发第一次
  tap()

  timer = setInterval(function() {
    tap()
  }, ms)

  return function cancel() {
    if (timer) {
      clearInterval(timer)
      timer = null
    }
  }
}

